            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount;
        }

        int[] order = new int[n];
        int[] parent = new int[n + 1];
        int qHead = 0;
        int qTail = 0;

        order[qTail++] = 1;
        parent[1] = -1;

        while (qHead < qTail) {
            int u = order[qHead++];
            for (int e = head[u]; e != 0; e = next[e]) {
                int v = to[e];
                if (v != parent[u]) {
                    parent[v] = u;
                    order[qTail++] = v;
                }
            }
        }

        int[] sz = new int[n + 1];
        int minDiff = n;

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            sz[u] += 1;
            if (u != 1) {
                int p = parent[u];
                sz[p] += sz[u];
                int diff = Math.abs(n - 2 * sz[u]);
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
        }

        System.out.println(minDiff);
    }
}
